def transpose(grid):
    if not grid or not grid[0]:
        return []
    return [[row[c] for row in grid] for c in range(len(grid[0]))]

from itertools import count, islice


def first_primes(n):
    """Return the first n prime channel numbers, lazily."""
    def is_prime(m):
        if m < 2:
            return False
        if m % 2 == 0:
            return m == 2
        d = 3
        while d * d <= m:      # only probe up to the square root
            if m % d == 0:
                return False
            d += 2
        return True

    stream = (p for p in count(2) if is_prime(p))  # infinite, lazy
    return list(islice(stream, n))
